## Why This Is Asked
Tests offline caching, data merging by id, and simple hook design for React Native with AsyncStorage.

## Key Concepts
- AsyncStorage usage for simple persistence
- useEffect/useState lifecycle and dependency on endpoint
- Merging lists by id while preserving user-visible order
- Exposing a small API (data, loading, error, refetch) for components

## Code Example
```javascript
import { useState, useEffect } from 'react';
import AsyncStorage from '@react-native-async-storage/async-storage';

export function useCacheList(endpoint) {
  const [data, setData] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const loadData = async () => {
      try {
        // Load cached data first
        const cached = await AsyncStorage.getItem(`cache_${endpoint}`);
        if (cached) {
          setData(JSON.parse(cached));
        }

        // Fetch fresh data
        const response = await fetch(endpoint);
        const freshData = await response.json();

        // Merge by id, preserving cached order
        const merged = mergeById(data, freshData);
        setData(merged);

        // Update cache
        await AsyncStorage.setItem(`cache_${endpoint}`, JSON.stringify(merged));
      } catch (err) {
        setError(err);
      } finally {
        setLoading(false);
      }
    };

    loadData();
  }, [endpoint]);

  return { data, loading, error, refetch: () => loadData() };
}

function mergeById(cached, fresh) {
  const map = new Map();

  // Preserve cached order
  cached.forEach(item => map.set(item.id, item));

  // Update with fresh data
  fresh.forEach(item => {
    if (map.has(item.id)) {
      map.set(item.id, item);
    } else {
      // Append new items
      cached.push(item);
    }
  });

  return Array.from(map.values());
}
```

## Component Example
```javascript
function EventsList() {
  const { data, loading, error } = useCacheList('/api/events');

  if (loading) return <ActivityIndicator />;
  if (error) return <Text>Error: {error.message}</Text>;

  return (
    <FlatList
      data={data}
      keyExtractor={item => item.id}
      renderItem={({ item }) => <EventCard event={item} />}
    />
  );
}
```

## Why This Is Asked
Tests ability to design a responsive image loading strategy that balances UX and data usage, incorporating network state, device capabilities, and offline caching in React Native.

## Key Concepts
- Variant selection logic using NetInfo, PixelRatio, and battery saver state
- Local caching strategy (Realm/SQLite) with TTL and cache busting
- Image loading lifecycle and prefetching to minimize jank

## Code Example
```javascript
import { useEffect, useState, useCallback } from 'react'
import NetInfo from '@react-native-community/netinfo'
import { PixelRatio } from 'react-native'

function useAdaptiveImage(sizes, baseUri) {
  const [uri, setUri] = useState(sizes.medium)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState(null)

  const resolveVariant = useCallback((info) => {
    const bandwidth = info.type === 'wifi' ? 1000 : info.details?.speed ?? 500
    const dpr = PixelRatio.get()
    const batterySaver = info.batterySaverEnabled
    let chosen = sizes.medium
    if (!batterySaver && bandwidth > 800 && dpr >= 2) chosen = sizes.large
    else if (bandwidth < 400) chosen = sizes.thumb
    return chosen
  }, [sizes])

  useEffect(() => {
    let mounted = true
    NetInfo.fetch().then(info => {
      if (!mounted) return
      const variant = resolveVariant(info)
      setUri(variant)
      // pretend fetch/cache logic here
      setLoading(false)
    }).catch(err => {
      if (mounted) { setError(err); setLoading(false) }
    })
    return () => { mounted = false }
  }, [resolveVariant])

  const refresh = useCallback(() => {
    setLoading(true)
    NetInfo.fetch().then(info => {
      const variant = resolveVariant(info)
      setUri(variant)
      setLoading(false)
    }).catch(err => setError(err))
  }, [resolveVariant])

  return { uri, loading, error, refresh }
}
```

